import{_ as o,o as r,c as a,ag as d}from"./chunks/framework.CAXxHpAX.js";const g=JSON.parse('{"title":"如何做到包容与接纳","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-包容与接纳.md","filePath":"20-专题研究/topic-包容与接纳.md","lastUpdated":null}'),e={name:"20-专题研究/topic-包容与接纳.md"};function l(n,t,h,s,u,q){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="如何做到包容与接纳" tabindex="-1">如何做到包容与接纳 <a class="header-anchor" href="#如何做到包容与接纳" aria-label="Permalink to &quot;如何做到包容与接纳&quot;">​</a></h1><blockquote><p>专题分析：包容的智慧——接纳不完美 组合模型：对法不执 + 圆融中和 + 天人合一 分级阅读：⚡ 速用 · 📖 标准 · 🔍 深入</p></blockquote><hr><h2 id="⚡-速用版-看对方不顺眼怎么办" tabindex="-1">⚡ 速用版：看对方不顺眼怎么办 <a class="header-anchor" href="#⚡-速用版-看对方不顺眼怎么办" aria-label="Permalink to &quot;⚡ 速用版：看对方不顺眼怎么办&quot;">​</a></h2><p><strong>① 破标签（对法不执）</strong>——&quot;他这个人就是这样&quot;——这个标签是你贴的。放下标签，他是一个不断变化的人。</p><blockquote><p>&quot;凡所有相，皆是虚妄&quot;——你看不顺眼的那个&quot;相&quot;，会变。</p></blockquote><p><strong>② 站整体（圆融中和）</strong>——从整体看：他有让你不舒服的地方，也有他的好。人不是单一面的。</p><blockquote><p>用一个缺点否定整个人——这是边见。</p></blockquote><p><strong>③ 一体观（天人合一）</strong>——他和你是同一个整体的一部分。排斥他，也是在排斥自己的一部分。</p><blockquote><p>真正的不顺眼，不是他不好——是你的&quot;我相&quot;在排斥跟你不一致的东西。</p></blockquote><hr><hr><h2 id="📖-一、包容的本质" tabindex="-1">📖 一、包容的本质 <a class="header-anchor" href="#📖-一、包容的本质" aria-label="Permalink to &quot;📖 一、包容的本质&quot;">​</a></h2><p>包容不是&quot;勉强接受&quot;，是<strong>看清之后自然放下</strong>。</p><p>了空居士很少用&quot;包容&quot;这个词，他的体系中有三个概念直接服务于包容：</p><blockquote><p><strong>&quot;和其光，同其尘&quot;</strong></p><p>— <a href="/60-原文段落/道德经4章-和光同尘">道德经4章-和光同尘</a></p></blockquote><blockquote><p><strong>&quot;是法平等，无有高下&quot;</strong></p><p>— <a href="/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a></p></blockquote><p>从三个模型看包容：</p><table tabindex="0"><thead><tr><th>模型角度</th><th>做什么</th><th>一句话</th></tr></thead><tbody><tr><td><strong>对法不执</strong></td><td>放下&quot;应该怎样&quot;的标准——标准不是你定的</td><td>你看不惯的是&quot;不符合你的标准&quot;</td></tr><tr><td><strong>圆融中和</strong></td><td>从整体看人——没有绝对的好人坏人</td><td>离了边见，包容自然发生</td></tr><tr><td><strong>天人合一</strong></td><td>一体观——他和我是同一个整体的不同部分</td><td>排斥他就是排斥我自己</td></tr></tbody></table><hr><h2 id="📖-二、包容的两个层次" tabindex="-1">📖 二、包容的两个层次 <a class="header-anchor" href="#📖-二、包容的两个层次" aria-label="Permalink to &quot;📖 二、包容的两个层次&quot;">​</a></h2><h3 id="_1-包容他人的不同" tabindex="-1">1. 包容他人的不同 <a class="header-anchor" href="#_1-包容他人的不同" aria-label="Permalink to &quot;1. 包容他人的不同&quot;">​</a></h3><blockquote><p><strong>&quot;和光同尘——收敛锋芒，不张扬，在光明之处能待，在凡俗之处也能待。&quot;</strong></p><p>— <a href="/60-原文段落/道德经4章-和光同尘">道德经4章-和光同尘</a></p></blockquote><p><strong>模型应用</strong>：</p><ul><li>对法不执：每个人有不同的活法——不是你的方法才是对的</li><li>圆融中和：不因为一个人跟你不&gt; 同就否定他—&gt; 整体观下，多样性是正常的</li></ul><h3 id="_2-包容自己的不完美" tabindex="-1">2. 包容自己的不完美 <a class="header-anchor" href="#_2-包容自己的不完美" aria-label="Permalink to &quot;2. 包容自己的不完美&quot;">​</a></h3><blockquote><p><strong>&quot;不可用心守，不可无意求&quot;</strong>——对自己也要这样：不苛责，不放任。</p><p>— <a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p></blockquote><p><strong>模型应用</strong>：</p><ul><li>天人合一：你也是自然的一部分——自然的东西就&gt; 是不完美的，这才是&quot;自然&quot;</li><li>对法不执：连&quot;我必须完美&quot;这个法都要放下</li></ul><hr><h2 id="📖-三、模型协同" tabindex="-1">📖 三、模型协同 <a class="header-anchor" href="#📖-三、模型协同" aria-label="Permalink to &quot;📖 三、模型协同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>模型</th><th>做什么</th><th>如果跳过</th></tr></thead><tbody><tr><td>① 破标准</td><td>对法不执</td><td>放下&quot;应该怎样&quot;的执着</td><td>一直在评判，无法包容</td></tr><tr><td>② 整体</td><td>圆融中和</td><td>从整体看人——不盯着一个缺点</td><td>以偏概全</td></tr><tr><td>③ 一体</td><td>天人合一</td><td>体会到你我本是一体</td><td>包容变成了&quot;忍耐&quot;——忍得了一时忍不了一世</td></tr></tbody></table><hr><h2 id="📖-四、案例拆解" tabindex="-1">📖 四、案例拆解 <a class="header-anchor" href="#📖-四、案例拆解" aria-label="Permalink to &quot;📖 四、案例拆解&quot;">​</a></h2><h3 id="案例一-受不了同事的做事方式" tabindex="-1">案例一：受不了同事的做事方式 <a class="header-anchor" href="#案例一-受不了同事的做事方式" aria-label="Permalink to &quot;案例一：受不了同事的做事方式&quot;">​</a></h3><p><strong>场景</strong>：同事做事慢、爱问问题、还总是打扰你。你忍了很久，越来越烦。</p><p><strong>✅ 介入</strong>：</p><ol><li><strong>破标准</strong>：&quot;做事应该快准狠&quot;这是你的标准——不是他的。他有自己的节奏。</li><li><strong>整体</strong>：他慢但他细心，出错少。整体看，你们互补。</li><li><strong>一体</strong>：同一团队——他弱的地方你的强，你弱的地方他强。不是&quot;谁对谁错&quot;，是&quot;怎么搭配更好&quot;。</li></ol><h3 id="案例二-不能原谅自己的失误" tabindex="-1">案例二：不能原谅自己的失误 <a class="header-anchor" href="#案例二-不能原谅自己的失误" aria-label="Permalink to &quot;案例二：不能原谅自己的失误&quot;">​</a></h3><p><strong>场景</strong>：你犯了一个低级错误，造成了损失。过去一个月了还在反复想&quot;我怎么这么蠢&quot;。</p><p><strong>✅ 介入</strong>：</p><ol><li><strong>破标准</strong>：&quot;我不应该犯错&quot;——这是执。了空居士说&quot;法尚应舍&quot;——圣贤都会犯错。</li><li><strong>整体</strong>：一次失误不等于你这个人不行。看你整体的表现。</li><li><strong>一体</strong>：你的不完美是自然的一部分。一棵树上有直枝也有弯枝——都正常。</li></ol><hr><h2 id="📖-五、常见误区" tabindex="-1">📖 五、常见误区 <a class="header-anchor" href="#📖-五、常见误区" aria-label="Permalink to &quot;📖 五、常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>包容=认可对方做得对</td><td>包容是理解，不是认同——你可以理解他为什么这样，同时不认可他的行为</td></tr><tr><td>包容=没有底线</td><td>&quot;了解就多帮助，不了解就少帮助&quot;——包容不等于不设边界</td></tr><tr><td>对自己包容=放纵</td><td>对自己包容是不苛责——但该做的还是要做</td></tr><tr><td>包容是天生的</td><td>包容是修出来的——越修心量越大</td></tr></tbody></table><hr><h2 id="🔍-六、理论边界" tabindex="-1">🔍 六、理论边界 <a class="header-anchor" href="#🔍-六、理论边界" aria-label="Permalink to &quot;🔍 六、理论边界&quot;">​</a></h2><ul><li><strong>包容 vs 纵容</strong>：了空居士说&quot;布施要有智慧&quot;——包容也一样。包容理解但不纵容恶行。整体观下有是非对错。</li><li><strong>自我接纳 vs 安于现状</strong>：接纳现在的自己不等于不进步——&quot;即得不等于得后&quot;——接纳当下的同时持续努力。</li></ul><hr><h2 id="🔍-七、模型原子" tabindex="-1">🔍 七、模型原子 <a class="header-anchor" href="#🔍-七、模型原子" aria-label="Permalink to &quot;🔍 七、模型原子&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型原子</th><th>包容中的应用</th></tr></thead><tbody><tr><td><strong>和光同尘</strong></td><td>融入不同的人和圈子，不标榜自己</td></tr><tr><td><strong>是法平等无有高下</strong></td><td>不同的活法没有高下之分</td></tr><tr><td><strong>法尚应舍</strong></td><td>连&quot;我的标准&quot;这个法都要放下</td></tr><tr><td><strong>离边见</strong></td><td>不用&quot;好/坏&quot;的二元标签看人</td></tr><tr><td><strong>整体观</strong></td><td>从整体看人——缺点是整体的一部分</td></tr><tr><td><strong>万法一体</strong></td><td>排斥他人就是排斥自己</td></tr></tbody></table><hr><h2 id="🔍-专题地图" tabindex="-1">🔍 专题地图 <a class="header-anchor" href="#🔍-专题地图" aria-label="Permalink to &quot;🔍 专题地图&quot;">​</a></h2><p><strong>前置专题</strong>：[人际关系] → 包容是人际关系的基础 <strong>进阶专题</strong>：[忍辱与原谅] → 从包容到超越伤害 <strong>推荐模型</strong>：<a href="/10-核心模型/model-对法不执">model-对法不执</a>、<a href="/10-核心模型/model-圆融中和">model-圆融中和</a>、<a href="/10-核心模型/model-天人合一">model-天人合一</a></p><hr><blockquote><p>创建日期：2026-05-09 | 素材来源：道德经第4章（和光同尘），金刚经第6分（法尚应舍）、第7分（整体观）、第23分（净心行善），五篇灵文。观点分析及分类归纳由笔者完成。</p></blockquote>',56)])])}const p=o(e,[["render",l]]);export{g as __pageData,p as default};
